import sys,struct,hashlib; sys.path.insert(0,'project')
from collector import Case, PRIM_INDEX
case={'primitive':'allreduce','mode':3,'root':0,'segments':1,'words':2,'capacity':1,'start':0,'events':[],'trace':5}
c=Case(0,3,0,1,2,1,0,5)
frames=[]
for r in range(4):
    frames.append((r, c.out_ack[r].build(0,None)))
for r in range(4):
    frames.append((r, c.out_data[r].build(0, struct.pack('!II',10,0xfffffffc))))
exp='785a920998439177a423274a1e4e4c6493cc4dc0df089322b71c22a0ce3a29eb'
def h(order, endian):
    sh=hashlib.sha256()
    for r,f in frames:
        if order=='rl': pre=bytes((r,))+struct.pack(endian+'I',len(f))
